.header-sidebar-wrapper, [data-pusher=sc-pushable-md], [data-pusher=sc-pushable-xs], body {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

/* editable({"type": "color", "label": "Body background"}) */
html,
body {
  font-family: "Montserrat", "Open Sans", "Helvetica Neue", Helvetica, Arial, sans-serif;
  background-color: #292c2f;
  font-size: 14px;
  min-height: 100%;
  height: auto;
}

body,
html,
div,
article,
aside,
section,
figure,
nav,
h1,
.cms-landing-page-about-us .about-staff-title,
.large-title-viewonly,
.large-title-navigable,
.large-title, h2, h3, h4, h5, h6,
p,
.push-button-secondary span,
.product-reviews-center-pusher span,
.product-details-information-pusher span,
.push-button-description span, pre, ul, ol, dl, address, a, input, textarea, button, fieldset {
  margin: 0;
  padding: 0;
  border: 0;
}

address {
  font-style: normal;
}

ul, li {
  list-style: none;
}

img {
  border: 0;
  max-width: 100%;
  height: auto;
}

a {
  color: #33cdb5;
  text-decoration: none;
  cursor: pointer;
  cursor: hand;
}

a:hover, .open a.sc-flyout-control, .open a.social-sharing-flyout-content-button, .open a.split-button-toggle, a:focus {
  color: #5cd7c4;
  text-decoration: none;
}

a:active {
  color: #416862;
}

[data-toggle=dropdown]:hover, .open [data-toggle=dropdown].sc-flyout-control, .open [data-toggle=dropdown].social-sharing-flyout-content-button, .open [data-toggle=dropdown].split-button-toggle, [data-toggle=dropdown]:focus {
  color: #404040;
}

.open > [data-toggle=dropdown] {
  color: #1c2127;
}

hr {
  height: 1px;
  border: 0;
  background-color: #d2e5ed;
}

* {
  -webkit-box-sizing: border-box;
  -moz-box-sizing: border-box;
  box-sizing: border-box;
}

::-webkit-scrollbar {
  width: 12px;
  height: 10px;
}

::-webkit-scrollbar-thumb {
  background: 0 0;
  background-color: #ccc;
  border: 2px solid transparent;
  border-radius: 10px;
  background-clip: padding-box;
}

::-webkit-scrollbar-thumb:hover, .open .sc-flyout-control::-webkit-scrollbar-thumb, .open .social-sharing-flyout-content-button::-webkit-scrollbar-thumb, .open .split-button-toggle::-webkit-scrollbar-thumb {
  background-color: #aaa;
}

::-webkit-scrollbar-track {
  background-color: #eaeaea;
  border-left: 1px solid #ccc;
}

.main, .layout-container {
  min-height: 100%;
  height: auto;
  width: 100%;
  background-color: white;
}
@media (min-width: 1600px) {
  .main, .layout-container {
    max-width: 1600px;
    margin: 0 auto;
  }
}
@media (min-width: 992px) {
  .main, .layout-container {
    height: auto;
  }
}

.shopping-layout {
  min-height: 100%;
}

.layout-overlay {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  width: 100%;
}

.cms-content ul,
.cms-content ol {
  margin-left: 20px;
}
.cms-content ul li {
  list-style: circle;
}
.cms-content ol li {
  list-style: decimal;
}

@media (min-width: 768px) and (max-width: 991px) {
  .container, .store-locator-upgrade-container, .store-locator-main, .store-locator-details, .store-locator-list-all-main, .cms-landing-page, .product-reviews-form, .product-reviews-form-preview, .product-reviews-form-confirmation, .product-reviews-center-footer, .product-reviews-center-review-container, .product-reviews-center-list, .product-details-information-content-container,
  .extra-pdp-info, .home-cms, .header-menu-level-container > li, .header-profile-menu-myaccount-container > li, .header-message .global-views-message, .header-message .product-reviews-form-confirmation-message, .header-message .product-line-stock-msg-not-available, .header-message .cookie-warning-banner-view, .footer-simplified-content, .facets-facet-browse-results .facets-empty, .facets-facet-browse-category-cells-container, .error-management-internal-error, .error-management-forbidden-error, .cart-detailed-body, .cart-detailed-view-header, .shopping-layout-breadcrumb, .shopping-layout-notifications, .nav-search-content, .site-search-content {
    width: auto;
  }
}
@media (max-width: 768px) {
  body.modal-open {
    position: fixed;
    margin: 0;
    width: 100%;
  }
}
.modal-backdrop {
  position: fixed;
}

[data-dropdown-content] {
  display: none;
}

.open [data-dropdown-content] {
  display: block;
}

.modal-open .modal {
  background: rgba(0, 0, 0, 0.4);
}

.modal-backdrop {
  position: fixed;
  z-index: 10;
}

td, th {
  vertical-align: top;
  padding-left: 15px;
  padding-right: 15px;
}

th {
  font-size: 14px;
  color: #999999;
}

.column-type-select, .transaction-line-views-cell-selectable-item-selector {
  padding-right: 0;
  width: 15px;
}
.column-type-select input, .transaction-line-views-cell-selectable-item-selector input {
  margin: 0;
}

.column-type-image, .transaction-line-views-cell-selectable-item-image, .transaction-line-views-cell-navigable-item-image, .transaction-line-views-cell-navigable-actionable-item-image {
  -webkit-box-sizing: content-box;
  -moz-box-sizing: content-box;
  box-sizing: content-box;
  width: 60px;
  min-width: 60px;
  text-align: center;
}
@media (min-width: 768px) {
  .column-type-image, .transaction-line-views-cell-selectable-item-image, .transaction-line-views-cell-navigable-item-image, .transaction-line-views-cell-navigable-actionable-item-image {
    width: 100px;
    min-width: 100px;
    padding-left: 15px;
    padding-right: 15px;
  }
}

.column-type-actions {
  min-width: 140px;
}
@media (min-width: 768px) {
  .column-type-actions {
    text-align: right;
  }
}

@media (min-width: 768px) {
  .column-type-number, .transaction-line-views-cell-selectable-col-reason, .transaction-line-views-cell-selectable-item-amount {
    text-align: right;
  }
}

@media (min-width: 768px) {
  .column-type-date {
    text-align: right;
  }
